--- src/bus.ts ---
/**
 * Hook bus for harness plugins (OpenCode-style hooks). The README states the contract:
 * handlers run one after another in subscription order, emit resolves after all of them,
 * a handler error rejects emit, and unsubscribing during an emit does not stop the others.
 */

export type Handler<T> = (payload: T) => void | Promise<void>;

export class HookBus {
  private handlers: Map<string, Handler<unknown>[]> = new Map();

  /** Subscribes a handler to an event; returns the function that unsubscribes it. */
  on<T>(event: string, handler: Handler<T>): () => void {
    const list = this.handlers.get(event) ?? [];
    list.push(handler as Handler<unknown>);
    this.handlers.set(event, list);
    return () => {
      const index = list.indexOf(handler as Handler<unknown>);
      if (index >= 0) {
        list.splice(index, 1);
      }
    };
  }

  /** Runs the handlers of an event with the payload. */
  async emit<T>(event: string, payload: T): Promise<void> {
    // Snapshot the list at emit start: handlers that unsubscribe themselves (or
    // another handler) during this emit still run; the change counts from the next emit.
    const list = [...(this.handlers.get(event) ?? [])];
    for (const handler of list) {
      // Awaiting each handler in turn keeps subscription order; a rejection
      // propagates out of emit and the remaining handlers do not run.
      await handler(payload);
    }
  }

  /** How many handlers an event has. */
  count(event: string): number {
    return (this.handlers.get(event) ?? []).length;
  }
}


--- tmp/verify.mjs ---
import { HookBus } from "../src/bus.ts";
import assert from "node:assert/strict";

// 1. Order: async handlers must settle in subscription order, not completion order.
{
  const bus = new HookBus();
  const order = [];
  bus.on("e", async () => { await new Promise(r => setTimeout(r, 30)); order.push("slow-first"); });
  bus.on("e", async () => { order.push("fast-second"); });
  await bus.emit("e", null);
  assert.deepEqual(order, ["slow-first", "fast-second"], "handlers must run in subscription order");
}

// 2. emit resolves only after every handler finished.
{
  const bus = new HookBus();
  let done = false;
  bus.on("e", async () => { await new Promise(r => setTimeout(r, 20)); done = true; });
  await bus.emit("e", null);
  assert.equal(done, true, "emit must await all handlers");
}

// 3. A failing hook rejects emit with the same error; later handlers do not run.
{
  const bus = new HookBus();
  const ran = [];
  bus.on("e", () => { ran.push("a"); });
  bus.on("e", () => { throw new Error("boom"); });
  bus.on("e", () => { ran.push("c"); });
  await assert.rejects(bus.emit("e", null), { message: "boom" }, "emit must reject with the handler error");
  assert.deepEqual(ran, ["a"], "handlers after the failing one must not run");
}

// 4. Self-unsubscribe during emit does not stop the others in that emit.
{
  const bus = new HookBus();
  const ran = [];
  const off = bus.on("e", () => { ran.push("a"); off(); });
  bus.on("e", () => { ran.push("b"); });
  await bus.emit("e", null);
  assert.deepEqual(ran, ["a", "b"], "self-unsubscribe must not stop the current emit");
  await bus.emit("e", null);
  assert.deepEqual(ran, ["a", "b", "b"], "unsubscribed handler must not run on the next emit");
}

console.log("all 4 symptom checks passed");
